{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break
    retained = set(node_map.keys())
    removed = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    def subtree_has_required(nid):
        if nid not in retained:
            return False
        if node_map[nid]['symbol'] in required_symbols:
            return True
        for child in children.get(nid, []):
            if child in retained and subtree_has_required(child):
                return True
        return False

    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if nid == root_id:
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        if any(child in retained for child in children.get(nid, [])):
            continue
        if subtree_has_required(nid):
            continue
        stack = [nid]
        while stack:
            curr = stack.pop()
            if curr not in retained:
                continue
            retained.discard(curr)
            for child in children.get(curr, []):
                if child in retained:
                    stack.append(child)
        removed.append(nid)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': sorted(retained)
    }"}
